class Solution:
    def checkString(self, s: str) -> bool:
        seen_b = False
        for ch in s:
            if ch == 'b':
                seen_b = True
            elif seen_b:
                return False
        return True

c.cpp:
class Solution {
public:
    bool checkString(string s) {
        bool seenB = false;
        for (char c : s) {
            if (c == 'b') seenB = true;
            else if (seenB) return false;
        }
        return true;
    }
};

